import 'dart:async';
import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';

const orange = Color(0xFFFF7A00);
const dark = Color(0xFF101114);
const supabaseUrl = String.fromEnvironment('SUPABASE_URL');
const supabaseKey = String.fromEnvironment('SUPABASE_ANON_KEY');

class PikachuWorkout extends StatelessWidget {
  const PikachuWorkout({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(debugShowCheckedModeBanner:false,title:'Pikachu Workout',theme:ThemeData(useMaterial3:true,colorSchemeSeed:orange),home:const AppGate());
}

class AppGate extends StatelessWidget {
  const AppGate({super.key});
  @override Widget build(BuildContext context) {
    if (supabaseUrl.isEmpty || supabaseKey.isEmpty) return const HomeShell();
    return StreamBuilder<AuthState>(stream:Supabase.instance.client.auth.onAuthStateChange,builder:(context,snap){
      return Supabase.instance.client.auth.currentSession == null ? const LoginPage() : const HomeShell();
    });
  }
}

class LoginPage extends StatefulWidget { const LoginPage({super.key}); @override State<LoginPage> createState()=>_LoginPageState(); }
class _LoginPageState extends State<LoginPage> {
  final email=TextEditingController(),password=TextEditingController(); bool signup=false,loading=false; String error='';
  Future<void> submit() async { setState(()=>loading=true); try { final a=Supabase.instance.client.auth; if(signup){await a.signUp(email:email.text.trim(),password:password.text);}else{await a.signInWithPassword(email:email.text.trim(),password:password.text);} } catch(e){if(mounted)setState(()=>error=e.toString());} finally{if(mounted)setState(()=>loading=false);} }
  @override Widget build(BuildContext c)=>Scaffold(backgroundColor:dark,body:SafeArea(child:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:Column(children:[const CircleAvatar(radius:58,backgroundColor:orange,child:Text('P',style:TextStyle(fontSize:58,fontWeight:FontWeight.w900,color:Colors.white))),const SizedBox(height:18),const Text('PIKACHU WORKOUT',style:TextStyle(color:Colors.white,fontSize:29,fontWeight:FontWeight.w900)),const SizedBox(height:28),TextField(controller:email,decoration:const InputDecoration(labelText:'Email',filled:true,fillColor:Colors.white,border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password',filled:true,fillColor:Colors.white,border:OutlineInputBorder())),if(error.isNotEmpty)Padding(padding:const EdgeInsets.all(8),child:Text(error,style:const TextStyle(color:Colors.redAccent))),const SizedBox(height:12),SizedBox(width:double.infinity,height:54,child:FilledButton(onPressed:loading?null:submit,child:Text(loading?'PLEASE WAIT':signup?'CREATE ACCOUNT':'LOGIN'))),TextButton(onPressed:()=>setState(()=>signup=!signup),child:Text(signup?'Already have an account? Login':'New here? Create account',style:const TextStyle(color:Colors.white)))]))));
}

