class WorkoutPlayer extends StatefulWidget { final Exercise? single; const WorkoutPlayer({super.key,this.single}); @override State<WorkoutPlayer> createState()=>_WorkoutPlayerState(); }
class _WorkoutPlayerState extends State<WorkoutPlayer>{late List<Exercise> list;int i=0,left=20;Timer? timer;bool running=true;@override void initState(){super.initState();list=widget.single==null?exercises:[widget.single!];start();}void start(){timer?.cancel();left=list[i].seconds>0?list[i].seconds:30;timer=Timer.periodic(const Duration(seconds:1),(_){if(!mounted||!running)return;if(left<=1){if(i<list.length-1){setState(()=>i++);left=list[i].seconds>0?list[i].seconds:30;}else{timer?.cancel();setState(()=>running=false);}}else setState(()=>left--);});}@override void dispose(){timer?.cancel();super.dispose();}@override Widget build(BuildContext c){final e=list[i];return Scaffold(backgroundColor:dark,appBar:AppBar(backgroundColor:dark,foregroundColor:Colors.white,title:Text('${i+1}/${list.length}')),body:Column(children:[Expanded(child:Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[ExerciseAnimation(exercise:e,size:240),const SizedBox(height:28),Text(e.name,style:const TextStyle(color:Colors.white,fontSize:28,fontWeight:FontWeight.w900)),const SizedBox(height:15),Text(e.reps>0?'× ${e.reps}':'${left}s',style:const TextStyle(color:orange,fontSize:60,fontWeight:FontWeight.w900))])),LinearProgressIndicator(value:(i+1)/list.length,minHeight:7),Padding(padding:const EdgeInsets.all(20),child:Row(children:[Expanded(child:OutlinedButton(onPressed:()=>setState(()=>running=!running),child:Text(running?'PAUSE':'RESUME'))),const SizedBox(width:12),Expanded(child:FilledButton(onPressed:(){if(i<list.length-1){setState(()=>i++);start();}},child:const Text('SKIP')))]))]));}}

